/////////////////////////////////
// cp_sret_m
//   Execute sret while sweeping cross-product of mprv, spp, spie, sie, tsr
//   Go to S or U mode depending on SPP.  SIE <- SPIE.  SPIE <- 1.  MPRV <- 0. SPP <- 0 (U-mode).  TSR has no effect.
/////////////////////////////////

# Setup
  CSRR(x8, mstatus)        # read and save mstatus
  LI(x10, 1 << 2)
  CSRC(medeleg, x10)          # turn off delegating illegal instruction exceptions so TSR won't cause a trap loop on sret
  # set up x10 with mstatus except MPRV, SPP, SPIE, SIE, TSR cleared
  LI(x13, 0x420122)          # x13 has all MPRV, SPP, SPIE, SIE, TSR bits set (bits [17], [8], [5], [1], [22] respectively)
  not x13, x13              # x13 has all but MPRV, SPP, SPIE, SIE, TSR bits set
  and x10, x8, x13          # clear MPRV, SPP, SPIE, SIE, TSR bits

# Testcase: sret from m-mode with spp = 0, mprv = 0, spie = 0, sie = 0, tsr = 0
  LI(x15, 0x00000000) # mprv = 0 spp = 0 spie = 0 sie = 0 tsr = 0
  or x15, x15, x10          # value to write to mstatus with MPRV/SPP/SPIE/SIE/TSR bits set/clear
  LA(x14, 1f)             # return address after sret
  CSRW(sepc, x14)          # set sepc to return address (if S mode exists).
  CSRW(mstatus, x15)       # write mstatus with MPRV/SPP/SPIE/SIE/TSR bits set/clear
S_sprivinst_cg_cp_sret_m_spp_0_mprv_0_spie_0_sie_0_tsr_0_wval:
  sret                   # test sret instruction, expect illegal instruction if S mode is not supported
  addi x15, zero, -1              # should not be executed
1:                         # sret should return to here
  # Check if x15 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x15, S_sprivinst_cg_cp_sret_m_spp_0_mprv_0_spie_0_sie_0_tsr_0_wval, S_sprivinst_cg_cp_sret_m_spp_0_mprv_0_spie_0_sie_0_tsr_0_wval_str)
  RVTEST_GOTO_MMODE      # make sure we return to machine mode
  # Read mstatus into x15 and check against expected.
  RVTEST_SIGUPD_CSR_READ(mstatus, x15, S_sprivinst_cg_cp_sret_m_spp_0_mprv_0_spie_0_sie_0_tsr_0_wval, S_sprivinst_cg_cp_sret_m_spp_0_mprv_0_spie_0_sie_0_tsr_0_wval_str)

