/////////////////////////////////
// cp_sret_s
//   Execute sret from S-mode while sweeping cross-product of sstatus.spp, spie, sie; mstatus.tsr
//   Go to S or U mode depending on SPP.  SIE <- SPIE.  SPIE <- 1.  MPRV <- 0. SPP <- 0 (U-mode).  TSR causes illegal instruction.
/////////////////////////////////

# Setup
  CSRR(x11, sstatus)        # read and save sstatus
  # set up x14 with sstatus except SPP, SPIE, SIE cleared
  LI(x12, 0x122)          # x12 has all SPP, SPIE, SIE bits set (bits [8], [5], [1] respectively)
  not x12, x12              # x12 has all but SPP, SPIE, SIE bits set
  and x14, x11, x12          # clear SPP, SPIE, SIE bits

# Set mstatus.TSR
  RVTEST_GOTO_MMODE      # enter machine mode for twiddling mstatus.TSR
  LI(x8, 4194304)  # mstatus.TSR bit
  CSRS(mstatus, x8)          # set TSR bit
  RVTEST_GOTO_LOWER_MODE Smode # return to supervisor mode to execute sret tests

# Testcase: sret from s-mode with spp = 0, spie = 0, sie = 0, tsr = 1
  LI(x8, 0x00000000) # spp = 0 spie = 0 sie = 0
  or x8, x8, x14          # value to write to sstatus with SPP/SPIE/SIE bits set/clear
  LA(x13, 1f)             # return address after sret
  CSRW(sepc, x13)          # set sepc to return address.
  CSRW(sstatus, x8)       # write sstatus with SPP/SPIE/SIE bits set/clear
