  CSRW(sepc, x13)          # set sepc to return address.
  CSRW(sstatus, x8)       # write sstatus with SPP/SPIE/SIE bits set/clear
S_sprivinst_cg_cp_sret_s_spp_1_spie_1_sie_1_tsr_0_wval:
  sret                   # test sret instruction
  addi x8, zero, -1              # should not be executed
1:                         # sret should return to here
  # Check if x8 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x8, S_sprivinst_cg_cp_sret_s_spp_1_spie_1_sie_1_tsr_0_wval, S_sprivinst_cg_cp_sret_s_spp_1_spie_1_sie_1_tsr_0_wval_str)
  RVTEST_GOTO_MMODE      # We might be coming from U-mode, so to get back to S-mode, macros may have to go through M
  RVTEST_GOTO_LOWER_MODE Smode      # make sure we return to supervisor mode
  # Read sstatus into x8 and check against expected.
  RVTEST_SIGUPD_CSR_READ(sstatus, x8, S_sprivinst_cg_cp_sret_s_spp_1_spie_1_sie_1_tsr_0_wval, S_sprivinst_cg_cp_sret_s_spp_1_spie_1_sie_1_tsr_0_wval_str)

  CSRW(sstatus, x11)    # restore CSR
  RVTEST_GOTO_MMODE      # back to M-mode to touch medeleg
  LI(x14, 1 << 2)
  CSRS(medeleg, x14)           # restore delegating illegal instructions


  RVTEST_GOTO_MMODE  # Get back to machine mode to prepare to go to supervisor mode
  RVTEST_GOTO_LOWER_MODE Smode  # Run remaining tests in supervisor mode


