/////////////////////////////////
// cp_sxlen_ge_uxlen
//   Ss1p13: from S-mode attempt to set sstatus.UXL = 1 and UXL = 2.
//   UXL=2 must be silently rejected when SXLEN=32 (UXLEN <= SXLEN).
/////////////////////////////////
  CSRR(x15, sstatus)


# Testcase: Ss1p13 attempt to set sstatus.UXL = 1 (uxlen32)
  CSRR(x10, sstatus)                     # read current sstatus into GPR
  LI(x14, 18446744060824649727)  # mask to clear UXL bits [33:32]
  and x10, x10, x14         # clear UXL bits [33:32]
  LI(x14, 4294967296)                        # UXL=1 shifted into position [33:32]
  or x10, x10, x14          # OR in desired UXL value
S_sstatus_cg_cp_sxlen_ge_uxlen_uxl_attempt_1:
  # Write x10 to sstatus, read back and check against expected.
  RVTEST_SIGUPD_CSR_WRITE(sstatus, x10, S_sstatus_cg_cp_sxlen_ge_uxlen_uxl_attempt_1, S_sstatus_cg_cp_sxlen_ge_uxlen_uxl_attempt_1_str)

# Testcase: Ss1p13 attempt to set sstatus.UXL = 2 (uxlen64)
  CSRR(x10, sstatus)                     # read current sstatus into GPR
  LI(x14, 18446744060824649727)  # mask to clear UXL bits [33:32]
  and x10, x10, x14         # clear UXL bits [33:32]
  LI(x14, 8589934592)                        # UXL=2 shifted into position [33:32]
  or x10, x10, x14          # OR in desired UXL value
S_sstatus_cg_cp_sxlen_ge_uxlen_uxl_attempt_2:
  # Write x10 to sstatus, read back and check against expected.
  RVTEST_SIGUPD_CSR_WRITE(sstatus, x10, S_sstatus_cg_cp_sxlen_ge_uxlen_uxl_attempt_2, S_sstatus_cg_cp_sxlen_ge_uxlen_uxl_attempt_2_str)

  CSRW(sstatus, x15)        # restore sstatus after Ss1p13 UXL tests
#endif // UDB_MXLEN_64
#endif // S1P13P0_SUPPORTED


/////////////////////////////////
// cp_sprivinst
//   Executing ecall and ebreak and mret should cause an exception
/////////////////////////////////

# Testcase: ecall instruction
S_sprivinst_cg_cp_sprivinst_ecall:
  ecall               # test ecall instruction
  nop                 # trap handler skips following instruction so this should not be executed

# Testcase: ebreak instruction
S_sprivinst_cg_cp_sprivinst_ebreak:
  ebreak              # test ebreak instruction
  nop                 # trap handler skips following instruction so this should not be executed

# Testcase: mret instruction
S_sprivinst_cg_cp_sprivinst_mret:
  mret                # test mret instruction
  nop                 # trap handler skips following instruction so this should not be executed

# Testcase: sfence.vma instruction
S_sprivinst_cg_cp_sprivinst_sfence_vma:
  sfence.vma          # test sfence.vma instruction
  nop                 # might be skipped


/////////////////////////////////
// cp_scsr_access
//   Read, write all 1s, write all 0s, set all 1s, set all 0s, restore all S-mode CSRs
/////////////////////////////////

# CSR Access Tests for sstatus
  CSRR(x10, sstatus)    # Save CSR
  LI(x8, -1)          # x8 = all 1s
#if __riscv_xlen == 64
  LI(x13, 0xffffffffff7fffbf)    # Load 64-bit mask
#else
  LI(x13, 0xff7fffbf)   # Load 32-bit mask (upper bits of 0xffffffffff7fffbf are ignored)
#endif
S_scsr_cg_cp_scsr_access_sstatus_csrrw1:
  CSRW(sstatus, x8)    # Write all 1s to CSR
  # Read sstatus into x14, keep only bits specified by mask, and check against expected.
  CSRR(x14, sstatus)    # Read CSR
  and x14, x14, x13    # keep only masked bits 0xffffffffff7fffbf
  # Check if x14 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x14, S_scsr_cg_cp_scsr_access_sstatus_csrrw1, S_scsr_cg_cp_scsr_access_sstatus_csrrw1_str)

S_scsr_cg_cp_scsr_access_sstatus_csrrw0:
  CSRW(sstatus, zero)   # Write all 0s to CSR
  # Read sstatus into x14, keep only bits specified by mask, and check against expected.
  CSRR(x14, sstatus)    # Read CSR
  and x14, x14, x13    # keep only masked bits 0xffffffffff7fffbf
  # Check if x14 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x14, S_scsr_cg_cp_scsr_access_sstatus_csrrw0, S_scsr_cg_cp_scsr_access_sstatus_csrrw0_str)

S_scsr_cg_cp_scsr_access_sstatus_csrs_all:
  CSRS(sstatus, x8)    # Set all CSR bits
  # Read sstatus into x14, keep only bits specified by mask, and check against expected.
  CSRR(x14, sstatus)    # Read CSR
  and x14, x14, x13    # keep only masked bits 0xffffffffff7fffbf
  # Check if x14 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x14, S_scsr_cg_cp_scsr_access_sstatus_csrs_all, S_scsr_cg_cp_scsr_access_sstatus_csrs_all_str)

S_scsr_cg_cp_scsr_access_sstatus_csrrc_all:
  CSRC(sstatus, x8)    # Clear all CSR bits
  # Read sstatus into x14, keep only bits specified by mask, and check against expected.
  CSRR(x14, sstatus)    # Read CSR
  and x14, x14, x13    # keep only masked bits 0xffffffffff7fffbf
  # Check if x14 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x14, S_scsr_cg_cp_scsr_access_sstatus_csrrc_all, S_scsr_cg_cp_scsr_access_sstatus_csrrc_all_str)
  CSRW(sstatus, x10)       # Restore CSR

# CSR Access Tests for sie
  CSRR(x15, sie)    # Save CSR
  LI(x12, -1)          # x12 = all 1s
S_scsr_cg_cp_scsr_access_sie_csrrw1:
  CSRW(sie, x12)    # Write all 1s to CSR
  # Read sie into x11 and check against expected.
  RVTEST_SIGUPD_CSR_READ(sie, x11, S_scsr_cg_cp_scsr_access_sie_csrrw1, S_scsr_cg_cp_scsr_access_sie_csrrw1_str)

S_scsr_cg_cp_scsr_access_sie_csrrw0:
  CSRW(sie, zero)   # Write all 0s to CSR
  # Read sie into x11 and check against expected.
  RVTEST_SIGUPD_CSR_READ(sie, x11, S_scsr_cg_cp_scsr_access_sie_csrrw0, S_scsr_cg_cp_scsr_access_sie_csrrw0_str)

S_scsr_cg_cp_scsr_access_sie_csrs_all:
  CSRS(sie, x12)    # Set all CSR bits
