  CSRS(sip, x13)    # Set all CSR bits
  # Read sip into x15 and check against expected.
  RVTEST_SIGUPD_CSR_READ(sip, x15, S_scsr_cg_cp_scsr_access_sip_csrs_all, S_scsr_cg_cp_scsr_access_sip_csrs_all_str)

