#ifndef SM1P11P0_SUPPORTED

# CSR Access Tests for senvcfg
  CSRR(x8, senvcfg)    # Save CSR
  LI(x11, -1)          # x11 = all 1s
#if __riscv_xlen == 64
  LI(x10, 0xffffffffffffffcf)    # Load 64-bit mask
#else
  LI(x10, 0xffffffcf)   # Load 32-bit mask (upper bits of 0xffffffffffffffcf are ignored)
#endif
S_scsr_cg_cp_scsr_access_senvcfg_csrrw1:
  CSRW(senvcfg, x11)    # Write all 1s to CSR
  # Read senvcfg into x12, keep only bits specified by mask, and check against expected.
  CSRR(x12, senvcfg)    # Read CSR
  and x12, x12, x10    # keep only masked bits 0xffffffffffffffcf
  # Check if x12 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x12, S_scsr_cg_cp_scsr_access_senvcfg_csrrw1, S_scsr_cg_cp_scsr_access_senvcfg_csrrw1_str)

