  and x12, x12, x10    # keep only masked bits 0xffffffffffffffcf
  # Check if x12 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x12, S_scsr_cg_cp_scsr_access_senvcfg_csrs_all, S_scsr_cg_cp_scsr_access_senvcfg_csrs_all_str)

