/////////////////////////////////
// cp_scsrwalk
//   Set and clear each bit individually in all writable S-mode CSRs
/////////////////////////////////

# CSR Walk Tests for sstatus
  CSRR(x12, sstatus)      # Save CSR
  LI(x13, 1)              # 1 in bit 0
  LI(x15, 18446744073701162943)    # Load mask (0xffffffffff7fffbf)
  LI(x10, -1)             # x10 = all 1s

  CSRW(sstatus, zero)    # clear all bits
  CSRS(sstatus, x13)     # set walking 1 in column 0
S_scsr_cg_cp_scsrwalk_sstatus_set_bit_0:
  # Read sstatus into x11, keep only bits specified by mask, and check against expected.
  CSRR(x11, sstatus)    # Read CSR
  and x11, x11, x15    # keep only masked bits 0xffffffffff7fffbf
  # Check if x11 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x11, S_scsr_cg_cp_scsrwalk_sstatus_set_bit_0, S_scsr_cg_cp_scsrwalk_sstatus_set_bit_0_str)
  slli x13, x13, 1      # walk the 1

  CSRW(sstatus, zero)    # clear all bits
  CSRS(sstatus, x13)     # set walking 1 in column 1
S_scsr_cg_cp_scsrwalk_sstatus_set_bit_1:
  # Read sstatus into x11, keep only bits specified by mask, and check against expected.
  CSRR(x11, sstatus)    # Read CSR
  and x11, x11, x15    # keep only masked bits 0xffffffffff7fffbf
  # Check if x11 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x11, S_scsr_cg_cp_scsrwalk_sstatus_set_bit_1, S_scsr_cg_cp_scsrwalk_sstatus_set_bit_1_str)
  slli x13, x13, 1      # walk the 1

  CSRW(sstatus, zero)    # clear all bits
  CSRS(sstatus, x13)     # set walking 1 in column 2
