/////////////////////////////////
// cp_scsr_from_m
//   Read, write all 1s, write all 0s, set all 1s, set all 0s, restore all S-mode CSRs from M-mode
/////////////////////////////////
  RVTEST_GOTO_MMODE      # enter machine mode for testing S-mode CSRs from M-mode


# CSR Access Tests for sstatus
  CSRR(x12, sstatus)    # Save CSR
  LI(x11, -1)          # x11 = all 1s
#if __riscv_xlen == 64
  LI(x10, 0xffffffffff7fffbf)    # Load 64-bit mask
#else
  LI(x10, 0xff7fffbf)   # Load 32-bit mask (upper bits of 0xffffffffff7fffbf are ignored)
#endif
S_scsr_cg_cp_scsr_from_m_sstatus_csrrw1:
  CSRW(sstatus, x11)    # Write all 1s to CSR
  # Read sstatus into x15, keep only bits specified by mask, and check against expected.
  CSRR(x15, sstatus)    # Read CSR
  and x15, x15, x10    # keep only masked bits 0xffffffffff7fffbf
  # Check if x15 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x15, S_scsr_cg_cp_scsr_from_m_sstatus_csrrw1, S_scsr_cg_cp_scsr_from_m_sstatus_csrrw1_str)

S_scsr_cg_cp_scsr_from_m_sstatus_csrrw0:
  CSRW(sstatus, zero)   # Write all 0s to CSR
  # Read sstatus into x15, keep only bits specified by mask, and check against expected.
  CSRR(x15, sstatus)    # Read CSR
  and x15, x15, x10    # keep only masked bits 0xffffffffff7fffbf
  # Check if x15 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x15, S_scsr_cg_cp_scsr_from_m_sstatus_csrrw0, S_scsr_cg_cp_scsr_from_m_sstatus_csrrw0_str)

S_scsr_cg_cp_scsr_from_m_sstatus_csrs_all:
  CSRS(sstatus, x11)    # Set all CSR bits
  # Read sstatus into x15, keep only bits specified by mask, and check against expected.
  CSRR(x15, sstatus)    # Read CSR
  and x15, x15, x10    # keep only masked bits 0xffffffffff7fffbf
  # Check if x15 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x15, S_scsr_cg_cp_scsr_from_m_sstatus_csrs_all, S_scsr_cg_cp_scsr_from_m_sstatus_csrs_all_str)

