/////////////////////////////////
// cp_shadow
//   Check that values written to shadowed registers are consistent between machine and supervisor mode
/////////////////////////////////
  LI(x10, 0x007FFFBF) # skip UBE, UXL bits which would cause weird behavior

# Testcase: shadow CSR test for writing mstatus and reading sstatus with mask 0xcffffffcf
  LI(x15, 0xcffffffcf) # mask specifying bits to keep
  csrr x14, mstatus       # save original value of mstatus
  csrw mstatus, x10       # write many 1s to mstatus
S_scsr_cg_cp_shadow_mstatus_sstatus_1s:
  # Read sstatus into x13, keep only bits specified by mask, and check against expected.
  CSRR(x13, sstatus)    # Read CSR
  and x13, x13, x15    # keep only masked bits 0xcffffffcf
  # Check if x13 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x13, S_scsr_cg_cp_shadow_mstatus_sstatus_1s, S_scsr_cg_cp_shadow_mstatus_sstatus_1s_str)
  csrw mstatus, x0       # write all 0s to mstatus
S_scsr_cg_cp_shadow_mstatus_sstatus_0s:
  # Read sstatus into x13, keep only bits specified by mask, and check against expected.
  CSRR(x13, sstatus)    # Read CSR
  and x13, x13, x15    # keep only masked bits 0xcffffffcf
  # Check if x13 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x13, S_scsr_cg_cp_shadow_mstatus_sstatus_0s, S_scsr_cg_cp_shadow_mstatus_sstatus_0s_str)
  csrw mstatus, x14       # write back saved value of mstatus

# Testcase: shadow CSR test for writing sstatus and reading mstatus with mask 0xcffffffcf
  LI(x15, 0xcffffffcf) # mask specifying bits to keep
  csrr x14, sstatus       # save original value of sstatus
  csrw sstatus, x10       # write many 1s to sstatus
