  RVTEST_SIGUPD(x2, x5, x4, x13, S_scsr_cg_cp_shadow_sstatus_mstatus_1s, S_scsr_cg_cp_shadow_sstatus_mstatus_1s_str)
  csrw sstatus, x0       # write all 0s to sstatus
S_scsr_cg_cp_shadow_sstatus_mstatus_0s:
  # Read mstatus into x13, keep only bits specified by mask, and check against expected.
  CSRR(x13, mstatus)    # Read CSR
